/* Tabs on Radix: state comes from data-state. The legacy .tab[aria-selected] rules still work for CSS-only markup. */
.tabs-root { display: grid; gap: var(--s4); }
.tabs-root[data-orientation="vertical"] { grid-template-columns: max-content 1fr; align-items: start; }
.tabs-list { display: flex; gap: var(--s5); border-bottom: 1px solid var(--rule); }
.tabs-list[data-orientation="vertical"] { flex-direction: column; gap: 0; border-bottom: 0; border-inline-end: 1px solid var(--rule); }
.tabs-trigger { overflow-wrap: anywhere; padding: var(--s3) 0; margin-bottom: -1px; font-weight: 500; color: var(--muted); border-bottom: 2px solid transparent; }
.tabs-list[data-orientation="vertical"] .tabs-trigger { padding-block: var(--s2); padding-inline: 0 var(--s4); margin-block: 0; margin-inline: 0 -1px; border-bottom: 0; border-inline-end: 2px solid transparent; text-align: start; }
.tabs-trigger:hover:not(:disabled) { color: var(--foreground); }
.tabs-trigger[data-state="active"] { color: var(--foreground); border-color: var(--foreground); }
.tabs-trigger:disabled { opacity: 0.5; cursor: not-allowed; }
.tabs-content:focus-visible { outline-offset: 4px; }

/* ─── Navigation: breadcrumb, pager, steps, top bar ─── */
.crumbs { min-width: 0; display: flex; flex-wrap: wrap; gap: var(--s2); font-size: var(--text-sm); color: var(--muted); }
.crumbs li + li::before { content: "/"; margin-inline-end: var(--s2); color: var(--ink-3); }
.crumbs [aria-current="page"] { color: var(--foreground); }
.pager { display: flex; flex-wrap: wrap; align-items: center; gap: var(--s2); font-size: var(--text-sm); }
.pager a, .pager button { min-width: 36px; padding: var(--s2) var(--s3); text-align: center; border: 1px solid var(--rule); text-decoration: none; }
.pager a:hover, .pager button:hover:not(:disabled) { border-color: var(--foreground); }
.pager [aria-current="page"] { background: var(--foreground); color: var(--background); border-color: var(--foreground); }
.pager button:disabled { opacity: 0.5; cursor: not-allowed; }
.steps { display: grid; grid-auto-flow: column; grid-auto-columns: 1fr; gap: var(--s3); counter-reset: step; }
.step { counter-increment: step; padding-top: var(--s3); border-top: 2px solid var(--rule); font-size: var(--text-sm); color: var(--muted); }
.step::before { content: counter(step, decimal-leading-zero); display: block; font-size: var(--text-xs); }
.step[data-state="done"] { border-top-color: var(--foreground); color: var(--foreground); }
.step[aria-current="step"] { border-top-color: var(--accent); color: var(--foreground); font-weight: 500; }
.topbar { display: flex; align-items: center; gap: var(--s5); padding: var(--s4) var(--s5); border-bottom: 1px solid var(--rule); flex-wrap: wrap; }
.topbar .brand { padding: 0; }
.topbar-nav { display: flex; flex-wrap: wrap; gap: var(--s5); margin-inline-end: auto; font-size: var(--text-sm); }
.topbar-nav a { text-decoration: none; color: var(--muted); }
.topbar-nav a:hover, .topbar-nav a[aria-current="page"] { color: var(--foreground); }
.tab[aria-selected="true"] { color: var(--foreground); box-shadow: inset 0 2px 0 var(--foreground); }
.tabpanel { padding-top: var(--s5); }
.tabpanel[hidden] { display: none; }
[dir="rtl"] .crumbs li + li::before { display: inline-block; transform: scaleX(-1); }

source.content:
import {forwardRef, type ComponentPropsWithoutRef, type ElementRef} from 'react';
import {Tabs as RadixTabs} from 'radix-ui';
import {cx} from '../../utils/cx';

/** The root of a tabbed interface. Use `value` and `onValueChange` (or `defaultValue`); put a `TabsList` and one `TabsContent` per tab inside. */
export const Tabs = forwardRef<ElementRef<typeof RadixTabs.Root>, ComponentPropsWithoutRef<typeof RadixTabs.Root>>(function Tabs({className, ...rest}, ref) {
  return <RadixTabs.Root ref={ref} className={cx('tabs-root', className)} {...rest} />;
});
/** The row of tab buttons. Arrow keys move between them. */
export const TabsList = forwardRef<ElementRef<typeof RadixTabs.List>, ComponentPropsWithoutRef<typeof RadixTabs.List>>(function TabsList({className, ...rest}, ref) {
  return <RadixTabs.List ref={ref} className={cx('tabs-list', className)} {...rest} />;
});
/** One tab button; its `value` must match a `TabsContent`. */
export const TabsTrigger = forwardRef<ElementRef<typeof RadixTabs.Trigger>, ComponentPropsWithoutRef<typeof RadixTabs.Trigger>>(function TabsTrigger({className, ...rest}, ref) {
  return <RadixTabs.Trigger ref={ref} className={cx('tabs-trigger', className)} {...rest} />;
});
/** The panel shown when the tab with the same `value` is selected. */
export const TabsContent = forwardRef<ElementRef<typeof RadixTabs.Content>, ComponentPropsWithoutRef<typeof RadixTabs.Content>>(function TabsContent({className, ...rest}, ref) {
  return <RadixTabs.Content ref={ref} className={cx('tabs-content', className)} {...rest} />;
});
